for slug,title,subject in [('python-basics','Python Basics','python'),('dsa-fundamentals','DSA Fundamentals','dsa'),('web-foundations','Web Foundations','html')]:
 qs=([{'prompt':'What does len([1, 2, 3]) return?','options':['2','3','4','An error'],'answer':1,'explanation':'len returns the number of elements in the list.'},{'prompt':'Which keyword defines a Python function?','options':['function','func','def','define'],'answer':2,'explanation':'Python uses def to introduce a function definition.'},{'prompt':'Which collection uses key-value pairs?','options':['list','tuple','set','dictionary'],'answer':3,'explanation':'A dictionary maps keys to values.'}] if subject=='python' else [{'prompt':'Which operation reads an array element by index?','options':['Lookup','Sort','Merge','Delete'],'answer':0,'explanation':'An indexed lookup retrieves an element at a known position.'},{'prompt':'What should you test in addition to normal input?','options':['Only large inputs','Boundary cases','Only random text','Nothing else'],'answer':1,'explanation':'Boundary cases reveal assumptions and off-by-one errors.'},{'prompt':'What makes a good learning example?','options':['Maximum complexity','No expected output','Small scope and clear expected output','No tests'],'answer':2,'explanation':'A small example makes behavior easy to reason about.'}])
 add('quiz','quizzes/'+slug,title+' Quiz','Check your understanding with explained multiple-choice questions.',category='Programming' if subject=='python' else 'Foundations',subject=subject,data={'questions':qs,'duration_minutes':10})
add('path','batch/dsa-step-by-step-learning','DSA Step-by-Step Learning','A guided sequence from arrays to algorithms, with resources and practice.', '## Your learning plan\n\nBuild a regular practice routine. Read a lesson, solve a problem, then review the explanation.',category='DSA',subject='dsa',data={'steps':[{'title':'Arrays and storage','path':'dsa/array-data-structure-guide','kind':'Read'},{'title':'Sorting algorithms','path':'dsa/quick-sort-algorithm','kind':'Read'},{'title':'Practice a coding problem','path':next(r['path'] for r in rows if r['type']=='problem'),'kind':'Practice'},{'title':'Check your understanding','path':'quizzes/dsa-fundamentals','kind':'Quiz'}],'duration':'4 weeks'})
add('path','learning-paths/python-foundations','Python Foundations','Start with variables, then lists and functions.','## Build a foundation\n\nWork through the resources in order, then take the quiz.',category='Programming',subject='python',data={'steps':[{'title':r['title'],'path':r['path'],'kind':'Read'} for r in rows if r['type']=='article' and r['subject']=='python']+ [{'title':'Python Basics Quiz','path':'quizzes/python-basics','kind':'Quiz'}],'duration':'2 weeks'})
for r in list(rows):
 if r['type']=='job':
  company=r['data'].get('company','AITrove Partner');slug=company.lower().replace(' ','-').replace('.','')
  r['data']['company_path']='companies/'+slug
  add('company','companies/'+slug,company,'Explore this employer and its available roles.','## Company overview\n\nThis is a sample company profile. Replace it with verified employer information before publishing.',data={'company':company,'location':r['data'].get('location','Remote'),'industry':'Technology'})
 if r['type']=='course':
  r['data'].setdefault('instructor','AITrove Editorial');r['data'].setdefault('instructor_path','authors/aitrove-editorial')
  r['data'].setdefault('batches',[{'title':'Self-paced preview','schedule':'Start at your own pace','seats':'Enrollment not open'}])
