add('business','gfg-hiring-solutions-for-recruiters','Hiring Solutions','Connect role requirements with practical skill assessment.','## Build a hiring plan\n\nDefine your role, assessment criteria and candidate experience.',data={'features':[{'title':'Role profiles','text':'Describe the skills your team needs.'},{'title':'Skill assessment','text':'Plan relevant exercises and review criteria.'}],'cta_label':'Discuss hiring','cta_url':'/about/contact-us'})
add('page','help','Help Center','Find answers about tutorials, practice, courses and your local preview.','## Getting started\n\nUse Tutorials to browse subjects, Practice to solve problems, and Courses to find structured programs.\n\n## Local preview\n\nBookmarks, quiz results and lesson progress stay in this browser. No learner account, payment or application is sent to a server.\n\n## Editorial administration\n\nUse the Editor link for the WordPress administration portal. WordPress hosting is not yet configured.')
